package dev.zomboidmelee.boxing;
import java.util.*;import net.minecraft.client.Minecraft;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.player.Player;import net.minecraft.world.InteractionHand;
public class Checks16{
 static int n;static void ok(boolean v,String message){n++;if(!v)throw new AssertionError(message);}public static class Stack{boolean empty;public Stack(boolean e){empty=e;}public boolean isEmpty(){return empty;}public String getDescriptionId(){return empty?"air":"tacz.weapon";}public Object getItem(){return this;}}
 public static class World{public long time=100;public boolean client;public boolean isClientSide(){return client;}public long getGameTime(){return time;}}
 public static class Key{public boolean down;public boolean isDown(){return down;}public boolean matchesMouse(int button){return button==0;}}public static class Options{public Key keyAttack=new Key();}
 public static class Hit{final String type;public Hit(String t){type=t;}public String getType(){return type;}}
 public static class Input{public boolean canceled,swing=true,attack=true;public boolean isAttack(){return attack;}public void setCanceled(boolean c){canceled=c;}public void setSwingHand(boolean s){swing=s;}}
 public static class Pose extends com.mojang.blaze3d.vertex.PoseStack{public int depth;public List<double[]>translations=new ArrayList<>();public void pushPose(){depth++;}public void popPose(){depth--;}public void translate(double x,double y,double z){translations.add(new double[]{x,y,z});}public void mulPose(org.joml.Quaternionf r){}}
 public static class Hand{public InteractionHand hand=InteractionHand.MAIN_HAND;public boolean canceled;public Pose pose=new Pose();public Buffer buffers=new Buffer();public Object getPoseStack(){return pose;}public Object getMultiBufferSource(){return buffers;}public int getPackedLight(){return 15728880;}public float getPartialTick(){return 0;}public InteractionHand getHand(){return hand;}public void setCanceled(boolean c){canceled=c;}}
 public static class Buffer extends net.minecraft.client.renderer.MultiBufferSource.BufferSource{public int flushes;public void endBatch(){flushes++;}}
 public static class Renderer extends net.minecraft.client.renderer.entity.player.PlayerRenderer{public int right,left;public void renderRightHand(com.mojang.blaze3d.vertex.PoseStack p,net.minecraft.client.renderer.MultiBufferSource b,int light,net.minecraft.client.player.AbstractClientPlayer player){right++;}public void renderLeftHand(com.mojang.blaze3d.vertex.PoseStack p,net.minecraft.client.renderer.MultiBufferSource b,int light,net.minecraft.client.player.AbstractClientPlayer player){left++;}}public static class Dispatcher{public Renderer renderer=new Renderer();public Renderer getRenderer(Player p){return renderer;}}
 public static class Part extends net.minecraft.client.model.geom.ModelPart{}public static class Model extends net.minecraft.client.model.PlayerModel<Object>{public Part head=new Part(),body=new Part(),rightLeg=new Part(),leftLeg=new Part();public Model(){rightArm=new Part();leftArm=new Part();rightSleeve=new Part();leftSleeve=new Part();}}
 public static class GeoBone{public float rotX;}public static class ShadowModel extends Model{public GeoBone rightArm=new GeoBone(),leftArm=new GeoBone();}

 public static class Tag{long until;public long getLong(String key){return until;}public void putLong(String key,long v){until=v;}}public static class Nav{int stops;public void stop(){stops++;}}public static class Victim{public double getX(){return 7;}public double getZ(){return 9;}public void push(double x,double y,double z){}public boolean hurtMarked;public boolean zombie=true;public Tag tag=new Tag();public World world=new World();public Nav nav=new Nav();public World level(){return world;}public Tag getPersistentData(){return tag;}public Nav getNavigation(){return nav;}}
 public static class DamageSource{public String kind="player";Object attacker,direct;public DamageSource(Object a,Object d){attacker=a;direct=d;}public Object getEntity(){return attacker;}public Object getDirectEntity(){return direct;}public String getMsgId(){return kind;}}public static class Damage{public Victim victim=new Victim();public DamageSource source;public float damage=1;public Victim getEntity(){return victim;}public DamageSource getSource(){return source;}public float getNewDamage(){return damage;}}
 public static void main(String[]a){Minecraft mc=Minecraft.INSTANCE;ServerPlayer p=new ServerPlayer();mc.player=p;
  ok(Boxing16.empty(p),"both empty");p.off=new Stack(false);ok(!Boxing16.empty(p),"offhand items suppress boxing");p.off=new Stack(true);p.main=new Stack(false);ok(!BoxingClient16.usable(p),"gun/melee/medical/item handoff");p.main=new Stack(true);ok(Boxing16.cooldown(55,p)==8,"eight-tick unarmed cooldown");p.main=new Stack(false);ok(Boxing16.cooldown(55,p)==55,"weapon cooldown preserved");p.main=new Stack(true);
  for(int clip=0;clip<2;clip++){double max=0,secondary=0;for(int i=0;i<=100;i++){double v=Motion16.value(clip,Motion16.DOMINANT[clip],i/100.0);ok(Double.isFinite(v)&&v>=0&&v<=1.001,"finite bounded source pose");max=Math.max(max,v);secondary=Math.max(secondary,Motion16.value(clip,1-Motion16.DOMINANT[clip],i/100.0));}ok(max>.75&&secondary<=.101,"one fist extends, other guards");ok(Motion16.value(clip,0,0)==0&&Motion16.value(clip,1,1)==0,"rejoins guard");}ok(Motion16.DOMINANT[0]!=Motion16.DOMINANT[1],"alternate left/right source punches");
  ok(!BoxingClient16.holdingReady(349999999,1)&&BoxingClient16.holdingReady(350000001,1),"350ms mining threshold");mc.options.keyAttack.down=true;mc.hitResult=new Hit("BLOCK");Input input=new Input();BoxingClient16.input(input);ok(input.canceled&&!input.swing,"short press is boxing, not mining");int swings=p.swings;BoxingClient16.input(new Input());ok(p.swings==swings,"no repeated swing packet while waiting for hold");BoxingClient16.pressed=System.nanoTime()-400000000;Input mine=new Input();BoxingClient16.input(mine);ok(!mine.canceled,"hold reaches native block mining");mc.options.keyAttack.down=false;BoxingClient16.tick(null);mc.hitResult=new Hit("ENTITY");Input hit=new Input();BoxingClient16.input(hit);ok(!hit.canceled,"entity attacks retain native server damage path");mc.hitResult=new Hit("MISS");BoxingClient16.nextPunch=0;Input air=new Input();BoxingClient16.input(air);ok(!air.canceled,"air punch remains vanilla-compatible after cooldown");
  Hand hand=new Hand();BoxingClient16.hand(hand);ok(hand.canceled&&mc.dispatcher.renderer.left==1&&mc.dispatcher.renderer.right==1&&hand.pose.depth==0,"both real skin arms rendered and pose stack restored");p.main=new Stack(false);Hand gun=new Hand();BoxingClient16.hand(gun);ok(!gun.canceled&&mc.dispatcher.renderer.right==1,"equipping a weapon immediately releases the renderer");p.main=new Stack(true);p.off=new Stack(false);Hand off=new Hand();BoxingClient16.hand(off);ok(!off.canceled,"offhand item renderer retained");p.off=new Stack(true);
  Model model=new Model();BoxingClient16.body(model,p);ok(model.rightArm.xRot<-1&&model.leftArm.xRot<-1,"third person permanent guard");ok(model.rightSleeve.xRot==model.rightArm.xRot&&model.leftSleeve.xRot==model.leftArm.xRot,"skin sleeves follow arms");ok(model.head.xRot==0&&model.body.xRot==0&&model.rightLeg.xRot==0&&model.leftLeg.xRot==0,"head torso legs unchanged for 3d armor");p.main=new Stack(false);Model weapon=new Model();BoxingClient16.body(weapon,p);ok(weapon.rightArm.xRot==0,"does not overwrite armed animation");p.main=new Stack(true);
  Damage d=new Damage();d.source=new DamageSource(p,p);Boxing16.hit(d);ok(d.victim.tag.until==108&&d.victim.nav.stops==1,"real zombie hit stuns eight ticks");d.victim.tag.until=140;Boxing16.hit(d);ok(d.victim.tag.until==140,"does not shorten existing shove stun");d.victim.tag.until=0;d.damage=0;Boxing16.hit(d);ok(d.victim.tag.until==0,"blocked/zero damage has no stun");d.damage=1;p.main=new Stack(false);Boxing16.hit(d);ok(d.victim.tag.until==0,"weapons do not receive fist stun");p.main=new Stack(true);d.source=new DamageSource(p,new Object());Boxing16.hit(d);ok(d.victim.tag.until==0,"projectile damage excluded");d.source=new DamageSource(p,p);d.source.kind="thorns";Boxing16.hit(d);ok(d.victim.tag.until==0,"thorns/indirect effects excluded even with empty hands");d.source.kind="player";d.victim.zombie=false;Boxing16.hit(d);ok(d.victim.tag.until==0,"players and other mobs excluded");ok(p.x==5&&p.y==7&&p.z==9,"no root displacement or forced movement");
  mc.screen=new Object();BoxingClient16.tick(null);ok(BoxingClient16.pressed==0,"opening a menu resets the hold timer");mc.screen=null;p.using=true;Hand medical=new Hand();BoxingClient16.hand(medical);ok(!medical.canceled,"treatment/item use respected");p.using=false;mc.player=null;BoxingClient16.tick(null);ok(BoxingClient16.owner==null,"disconnect releases animation state");
  System.out.println("BOXING_GUARD_ATTACK_MINING_HANDOFF_STUN_ARMOR_CHECKS="+n);
 }
}
